/// Configuration of the optional AI report backend.
///
/// The app never holds an AI API key. Reports are generated by a Cloud
/// Function you deploy (see `functions_example/`), and the app only knows its
/// URL. Pass it at build time:
///
///   flutter run --dart-define=AI_REPORT_ENDPOINT=https://<region>-<project>.cloudfunctions.net/generateReport
///
/// When the value is empty, [AiReportService] silently keeps using its
/// built-in templates, so nothing breaks in development.
class AiConfig {
  AiConfig._();

  static const String reportEndpoint =
      String.fromEnvironment('AI_REPORT_ENDPOINT');

  static bool get isConfigured => reportEndpoint.isNotEmpty;

  /// Hard cap so the UI never hangs on a slow backend.
  static const Duration timeout = Duration(seconds: 25);
}
